  public static func createRDE(
    _ fbb: inout FlatBufferBuilder,
    RDE_IDOffset RDE_ID: Offset,
    BODY_NAMEOffset BODY_NAME: Offset,
    BODY_NAIF_ID: Int32 = 0,
    NORAD_CAT_ID: UInt32 = 0,
    OBJECT_IDOffset OBJECT_ID: Offset = Offset(),
    WINDOW_STARTOffset WINDOW_START: Offset,
    WINDOW_ENDOffset WINDOW_END: Offset,
    RBF_RECORD_IDSVectorOffset RBF_RECORD_IDS: Offset = Offset(),
    SPACE_WEATHER_REFSVectorOffset SPACE_WEATHER_REFS: Offset = Offset(),
    SHIELDINGOffset SHIELDING: Offset = Offset(),
    INSTANT_DOSE_RATE_MSV_H: Double = 0.0,
    ORBIT_AVG_DOSE_RATE_MSV_H: Double = 0.0,
    MISSION_DOSE_MSV: Double = 0.0,
    TID_KRAD_SI: Double = 0.0,
    EFFECT_SEVERITY: rdeEffectSeverity = .unspecified,
    PASS_DOSESVectorOffset PASS_DOSES: Offset = Offset(),
    SHIELDING_CURVEVectorOffset SHIELDING_CURVE: Offset = Offset(),
    ELECTRONICSOffset ELECTRONICS: Offset = Offset(),
    CREWOffset CREW: Offset = Offset(),
    SEP_EFFECTSVectorOffset SEP_EFFECTS: Offset = Offset(),
    PROVENANCEOffset PROVENANCE: Offset
  ) -> Offset {
    let __start = RDE.startRDE(&fbb)
    RDE.add(RDE_ID: RDE_ID, &fbb)
    RDE.add(BODY_NAME: BODY_NAME, &fbb)
    RDE.add(BODY_NAIF_ID: BODY_NAIF_ID, &fbb)
    RDE.add(NORAD_CAT_ID: NORAD_CAT_ID, &fbb)
    RDE.add(OBJECT_ID: OBJECT_ID, &fbb)
    RDE.add(WINDOW_START: WINDOW_START, &fbb)
    RDE.add(WINDOW_END: WINDOW_END, &fbb)
    RDE.addVectorOf(RBF_RECORD_IDS: RBF_RECORD_IDS, &fbb)
    RDE.addVectorOf(SPACE_WEATHER_REFS: SPACE_WEATHER_REFS, &fbb)
    RDE.add(SHIELDING: SHIELDING, &fbb)
    RDE.add(INSTANT_DOSE_RATE_MSV_H: INSTANT_DOSE_RATE_MSV_H, &fbb)
    RDE.add(ORBIT_AVG_DOSE_RATE_MSV_H: ORBIT_AVG_DOSE_RATE_MSV_H, &fbb)
    RDE.add(MISSION_DOSE_MSV: MISSION_DOSE_MSV, &fbb)
    RDE.add(TID_KRAD_SI: TID_KRAD_SI, &fbb)
    RDE.add(EFFECT_SEVERITY: EFFECT_SEVERITY, &fbb)
    RDE.addVectorOf(PASS_DOSES: PASS_DOSES, &fbb)
    RDE.addVectorOf(SHIELDING_CURVE: SHIELDING_CURVE, &fbb)
    RDE.add(ELECTRONICS: ELECTRONICS, &fbb)
    RDE.add(CREW: CREW, &fbb)
    RDE.addVectorOf(SEP_EFFECTS: SEP_EFFECTS, &fbb)
    RDE.add(PROVENANCE: PROVENANCE, &fbb)
    return RDE.endRDE(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.RDE_ID, fieldName: "RDE_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.BODY_NAME, fieldName: "BODY_NAME", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.BODY_NAIF_ID, fieldName: "BODY_NAIF_ID", required: false, type: Int32.self)
    try _v.visit(field: VT.NORAD_CAT_ID, fieldName: "NORAD_CAT_ID", required: false, type: UInt32.self)
    try _v.visit(field: VT.OBJECT_ID, fieldName: "OBJECT_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.WINDOW_START, fieldName: "WINDOW_START", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.WINDOW_END, fieldName: "WINDOW_END", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.RBF_RECORD_IDS, fieldName: "RBF_RECORD_IDS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.SPACE_WEATHER_REFS, fieldName: "SPACE_WEATHER_REFS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.SHIELDING, fieldName: "SHIELDING", required: false, type: ForwardOffset<RDEShielding>.self)
    try _v.visit(field: VT.INSTANT_DOSE_RATE_MSV_H, fieldName: "INSTANT_DOSE_RATE_MSV_H", required: false, type: Double.self)
    try _v.visit(field: VT.ORBIT_AVG_DOSE_RATE_MSV_H, fieldName: "ORBIT_AVG_DOSE_RATE_MSV_H", required: false, type: Double.self)
    try _v.visit(field: VT.MISSION_DOSE_MSV, fieldName: "MISSION_DOSE_MSV", required: false, type: Double.self)
    try _v.visit(field: VT.TID_KRAD_SI, fieldName: "TID_KRAD_SI", required: false, type: Double.self)
    try _v.visit(field: VT.EFFECT_SEVERITY, fieldName: "EFFECT_SEVERITY", required: false, type: rdeEffectSeverity.self)
    try _v.visit(field: VT.PASS_DOSES, fieldName: "PASS_DOSES", required: false, type: ForwardOffset<Vector<ForwardOffset<RDEPassDose>, RDEPassDose>>.self)
    try _v.visit(field: VT.SHIELDING_CURVE, fieldName: "SHIELDING_CURVE", required: false, type: ForwardOffset<Vector<ForwardOffset<RDEShieldCurvePoint>, RDEShieldCurvePoint>>.self)
    try _v.visit(field: VT.ELECTRONICS, fieldName: "ELECTRONICS", required: false, type: ForwardOffset<RDEElectronicsEffect>.self)
    try _v.visit(field: VT.CREW, fieldName: "CREW", required: false, type: ForwardOffset<RDECrewDose>.self)
    try _v.visit(field: VT.SEP_EFFECTS, fieldName: "SEP_EFFECTS", required: false, type: ForwardOffset<Vector<ForwardOffset<RDESepEffect>, RDESepEffect>>.self)
    try _v.visit(field: VT.PROVENANCE, fieldName: "PROVENANCE", required: true, type: ForwardOffset<PVN>.self)
    _v.finish()
  }
